// Necromunda gang builder — standalone page, same account plumbing as the
// builders SPA. The catalog comes from /api/builders/necromunda/catalog
// (generated by scripts/necromunda-build-catalog.mjs — see its meta block for
// sources and honesty notes). Gangs live in localStorage under
// 'necromunda-gangs'; nothing is stored server-side.

// Discord SSO hands the session token back in the URL fragment.
(() => {
  const m = location.hash.match(/^#sso=([a-f0-9]+)$/);
  if (m) {
    localStorage.setItem('mol_token', m[1]);
    history.replaceState(null, '', location.pathname);
  }
})();

const $app = document.getElementById('app');
const token = localStorage.getItem('mol_token');
const SAVE_KEY = 'necromunda-gangs';
let me = null;
let discordSso = false;
let CAT = null;          // catalog
let gang = null;         // working gang
const openArm = new Set();   // expanded armoury items

// Unlike the SPA's esc(), this also escapes quotes: catalog names like
// '"Renderizer" Serrated Axe' land inside attribute values and onclick args.
function esc(s) {
  const d = document.createElement('div');
  d.textContent = s == null ? '' : String(s);
  return d.innerHTML.replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

async function api(path, opts = {}) {
  const headers = { 'Content-Type': 'application/json' };
  if (token) headers.Authorization = 'Bearer ' + token;
  const res = await fetch('/api' + path, { headers, ...opts });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(data.error || 'server said no');
  return data;
}

function toast(msg) {
  const el = document.createElement('div');
  el.className = 'toast';
  el.textContent = msg;
  document.body.append(el);
  setTimeout(() => el.remove(), 2400);
}

function loginWall() {
  const href = discordSso ? '/api/auth/discord?return=/builders/necromunda/' : '/play/';
  $app.innerHTML = `
    <h1>Necromunda</h1>
    <div class="sub">Members only</div>
    <div class="card" style="text-align:center;padding:40px">
      <p class="muted" style="margin-bottom:20px">Da gang builder is for club members.<br>
      Log in wiv yer Discord to get in.</p>
      <a class="btn" href="${href}">Log in with Discord</a>
    </div>`;
}

// ---------------------------------------------------------------- helpers

const uid = () => Math.random().toString(16).slice(2, 10);
const saves = () => { try { return JSON.parse(localStorage.getItem(SAVE_KEY)) || {}; } catch { return {}; } };
const setSaves = (s) => localStorage.setItem(SAVE_KEY, JSON.stringify(s));

const gangDef = () => CAT.gangs[gang.gangKey];
const fighterDef = (type) => gangDef().fighters.find((f) => f.name === type);
const equipDef = (name) => gangDef().equipment.find((e) => e.name === name);

function fighterTotal(f) {
  const def = fighterDef(f.type);
  return (def ? def.cost : 0) + f.gear.reduce((s, g) => s + (equipDef(g)?.cost || 0), 0);
}
const spent = () => gang.fighters.reduce((s, f) => s + fighterTotal(f), 0);

// Target-number stats print as "n+", movement as inches; 0 means n/a (crew).
const STAT_COLS = [
  ['m', 'M', (v) => (v ? v + '"' : '-')],
  ['ws', 'WS', plus], ['bs', 'BS', plus],
  ['s', 'S', flat], ['t', 'T', flat], ['w', 'W', flat],
  ['i', 'I', plus], ['a', 'A', flat],
  ['ld', 'Ld', plus], ['cl', 'Cl', plus], ['wil', 'Wil', plus], ['int', 'Int', plus],
];
function plus(v) { return v ? v + '+' : '-'; }
function flat(v) { return v || (v === 0 ? '-' : '-'); }

function statlineHtml(stats) {
  return `<div class="profile-wrap"><table class="statline">
    <tr>${STAT_COLS.map(([, h]) => `<th>${h}</th>`).join('')}</tr>
    <tr>${STAT_COLS.map(([k, , f]) => `<td>${f(stats[k])}</td>`).join('')}</tr>
  </table></div>`;
}

function statSummary(stats) {
  return STAT_COLS.map(([k, h, f]) => `${h}${f(stats[k])}`).join(' ');
}

// ---------------------------------------------------------------- warnings

const GANG_FIGHTER_CATS = ['Ganger', 'Juve'];
const JUVE_OK_CATS = ['Pistols', 'Close Combat', 'Grenades'];

function warnings() {
  const w = [];
  const by = (cat) => gang.fighters.filter((f) => fighterDef(f.type)?.category === cat);
  const leaders = by('Leader').length;
  if (leaders === 0) w.push('No Leader — a gang must include exactly one.');
  if (leaders > 1) w.push(`${leaders} Leaders — a gang may only have one.`);
  const gf = gang.fighters.filter((f) => GANG_FIGHTER_CATS.includes(fighterDef(f.type)?.category)).length;
  const others = gang.fighters.length - gf;
  if (gang.fighters.length && gf < others) {
    w.push('Gangers and Juves must make up at least half the gang (Gang Fighter rule).');
  }
  const specialists = gang.fighters.filter((f) => fighterDef(f.type)?.specialist).length;
  if (specialists > 1) w.push(`${specialists} Specialists — only one Ganger may be a Specialist at gang founding.`);
  if (spent() > gang.budget) w.push(`Over budget by ${spent() - gang.budget} credits.`);
  for (const f of gang.fighters) {
    const def = fighterDef(f.type);
    if (!def || !['Juve', 'Prospect'].includes(def.category)) continue;
    const bad = f.gear.filter((g) => !JUVE_OK_CATS.includes(equipDef(g)?.category));
    if (bad.length) w.push(`${f.label || def.name}: Juves/Prospects may normally only take pistols, close combat weapons and grenades (${bad.join(', ')}).`);
  }
  return w;
}

// ---------------------------------------------------------------- views

function render() {
  if (!gang) return renderChooser();
  renderBuilder();
}

function renderChooser() {
  const saved = saves();
  const savedHtml = Object.keys(saved).length ? `
    <h2>Saved Gangs</h2>
    <div class="card-grid">${Object.entries(saved).map(([n, g], i) => `
      <div class="card gang-card builder-card" onclick="NM.load(${i})">
        <div class="game">${esc(CAT.gangs[g.gangKey]?.name || g.gangKey)}</div>
        <h3>${esc(n)}</h3>
        <div class="meta">${g.fighters.length} fighters — rating ${g.fighters.reduce((s, f) => s + ((CAT.gangs[g.gangKey]?.fighters.find((d) => d.name === f.type)?.cost) || 0) + f.gear.reduce((t, x) => t + (CAT.gangs[g.gangKey]?.equipment.find((e) => e.name === x)?.cost || 0), 0), 0)}cr</div>
      </div>`).join('')}
    </div>` : '';

  $app.innerHTML = `
    <h1>Necromunda Gang Builder</h1>
    <div class="sub">${esc(CAT.meta.game)} — ${esc(CAT.meta.edition)}</div>
    <h2>Start a Gang</h2>
    <div class="gang-grid">${Object.entries(CAT.gangs).map(([key, g]) => `
      <div class="card gang-card builder-card" onclick="NM.newGang('${key}')">
        <div class="game">${esc(g.book)}</div>
        <h3>${esc(g.name)}</h3>
        <div class="meta">${g.fighters.length} fighter types — house skill: ${esc(g.houseSkill)}</div>
      </div>`).join('')}
    </div>
    ${savedHtml}
    <p class="muted" style="margin-top:20px">Catalog sources an' caveats are listed on every export —
    prices marked in the books always win an argument over this builder.</p>`;
}

function renderBuilder() {
  const g = gangDef();
  const total = spent();
  const warns = warnings();
  const over = total > gang.budget;

  $app.innerHTML = `
    <div class="crumb"><a href="#" onclick="NM.back();return false">← all gangs</a></div>
    <h1>${esc(g.name)} Gang</h1>
    <div class="sub">${esc(g.book)} — house skill: ${esc(g.houseSkill)}</div>
    ${warns.length ? `<div class="warnbox"><ul>${warns.map((w) => `<li>${esc(w)}</li>`).join('')}</ul></div>` : ''}
    <div class="bt-layout">
      <div class="bt-pane bt-filters">
        <h2>Gang</h2>
        <label>Gang name
          <input id="gname" value="${esc(gang.name)}" maxlength="40" onchange="NM.setName(this.value)">
        </label>
        <label>Credits budget
          <input id="gbudget" type="number" min="0" step="5" value="${gang.budget}" onchange="NM.setBudget(this.value)">
        </label>
        <div class="force-actions">
          <button class="btn small" onclick="NM.save()">Save</button>
          <button class="btn small ghost" onclick="NM.exportSheet()">Export</button>
        </div>
        <h2 style="margin-top:20px">Saved</h2>
        ${Object.keys(saves()).map((n, i) => `
          <div class="stafrow"><a href="#" onclick="NM.load(${i});return false">${esc(n)}</a>
            <button class="rmbtn" title="delete" onclick="NM.del(${i})">✕</button></div>`).join('') || '<p class="muted">Nothing saved yet.</p>'}
      </div>

      <div class="bt-pane">
        <h2>Recruit</h2>
        <div class="bt-scroll">
          <table class="nm-table">
            <tr><th class="c-add"></th><th class="c-name">Fighter</th><th class="c-cost">Cost</th></tr>
            ${g.fighters.map((f, i) => `
              <tr>
                <td class="c-add"><button class="addbtn" title="add ${esc(f.name)}" onclick="NM.add(${i})">+</button></td>
                <td class="c-name"><span class="uname">${esc(f.name)}</span>
                  <span class="fcat">${esc(f.category)}${f.specialist ? ' — specialist' : ''}</span>
                  <span class="fstat">${statSummary(f.stats)}</span>
                  ${f.note ? `<span class="fstat">${esc(f.note)}</span>` : ''}</td>
                <td class="c-cost"><span class="cr">${f.cost}</span></td>
              </tr>`).join('')}
          </table>
          <div class="armoury">
            <h2 style="margin-top:18px">Armoury</h2>
            ${armouryHtml(g)}
          </div>
        </div>
      </div>

      <div class="bt-pane">
        <h2>Roster</h2>
        <div class="credit-meter">
          <div class="box"><span class="lbl">Budget</span><b>${gang.budget}</b></div>
          <div class="box ${over ? 'over' : ''}"><span class="lbl">Spent</span><b>${total}</b></div>
          <div class="box"><span class="lbl">Rating</span><b>${total}</b></div>
        </div>
        <p class="muted" style="margin-bottom:10px">${gang.fighters.length} fighters — ${Math.max(0, gang.budget - total)} credits left</p>
        ${gang.fighters.map(fighterCardHtml).join('') || '<p class="muted">No fighters yet — recruit from the middle pane.</p>'}
      </div>
    </div>`;
}

function armouryHtml(g) {
  const cats = [...new Set(g.equipment.map((e) => e.category))];
  return cats.map((cat) => `
    <h3>${esc(cat)}</h3>
    ${g.equipment.map((e, i) => [e, i]).filter(([e]) => e.category === cat).map(([e, i]) => {
      const wpn = CAT.weapons[e.name];
      const open = openArm.has(e.name);
      return `<div class="arm-row" onclick="NM.toggleArm(${i})">
          <span>${esc(e.name)}${e.note ? ` <span class="muted">(${esc(e.note)})</span>` : ''}</span>
          <span class="cr">${e.cost}</span>
        </div>
        ${open && wpn ? profileHtml(wpn) : ''}
        ${open && !wpn ? `<p class="muted" style="padding:2px 2px 8px">${esc(CAT.wargear[e.name]?.note || 'Wargear — no weapon profile.')}</p>` : ''}`;
    }).join('')}`).join('');
}

function profileHtml(wpn) {
  return `<div class="profile-wrap"><table class="profile-table">
    <tr><th></th><th>Rng S</th><th>Rng L</th><th>Acc S</th><th>Acc L</th><th>Str</th><th>AP</th><th>D</th><th>Am</th><th>Traits</th></tr>
    ${wpn.profiles.map((p) => `
      <tr><td>${esc(p.name || '')}</td><td>${esc(p.rngS)}</td><td>${esc(p.rngL)}</td><td>${esc(p.accS)}</td><td>${esc(p.accL)}</td>
      <td>${esc(p.str)}</td><td>${esc(p.ap)}</td><td>${esc(p.d)}</td><td>${esc(p.ammo)}</td><td>${esc(p.traits)}</td></tr>`).join('')}
  </table></div>`;
}

function fighterCardHtml(f) {
  const def = fighterDef(f.type);
  if (!def) return '';
  const g = gangDef();
  return `<div class="fighter-card">
    <div class="fc-head">
      <input value="${esc(f.label)}" maxlength="30" placeholder="${esc(def.name)}"
        onchange="NM.rename('${f.id}', this.value)">
      <span class="fc-cost">${fighterTotal(f)}cr</span>
      <button class="rmbtn" title="remove fighter" onclick="NM.remove('${f.id}')">✕</button>
    </div>
    <div class="fc-type">${esc(def.name)} — ${esc(def.category)}${def.specialist ? ' (specialist)' : ''} — base ${def.cost}cr</div>
    ${statlineHtml(def.stats)}
    ${f.gear.map((gear, i) => `
      <div class="gear-row"><span>${esc(gear)}</span>
        <span class="g-cost">${equipDef(gear)?.cost ?? '?'}cr
          <button class="rmbtn" title="remove" onclick="NM.dropGear('${f.id}', ${i})">✕</button></span>
      </div>`).join('')}
    <div class="gear-add">
      <select id="sel-${f.id}">
        ${g.equipment.map((e) => `<option value="${esc(e.name)}">${esc(e.name)} — ${e.cost}cr</option>`).join('')}
      </select>
      <button class="btn small ghost" onclick="NM.addGear('${f.id}')">Equip</button>
    </div>
  </div>`;
}

// ---------------------------------------------------------------- actions

const NM = {
  newGang(key) {
    gang = { name: `${CAT.gangs[key].name} Gang`, gangKey: key, budget: CAT.meta.rules.startingCredits, fighters: [] };
    render();
  },
  back() { gang = null; render(); },
  setName(v) { gang.name = v.trim() || gang.name; render(); },
  setBudget(v) { gang.budget = Math.max(0, parseInt(v, 10) || 0); render(); },
  add(i) {
    const def = gangDef().fighters[i];
    if (!def) return;
    gang.fighters.push({ id: uid(), type: def.name, label: '', gear: [] });
    render();
  },
  remove(id) { gang.fighters = gang.fighters.filter((f) => f.id !== id); render(); },
  rename(id, v) { const f = gang.fighters.find((x) => x.id === id); if (f) f.label = v.trim(); },
  addGear(id) {
    const f = gang.fighters.find((x) => x.id === id);
    const sel = document.getElementById('sel-' + id);
    if (f && sel && sel.value) { f.gear.push(sel.value); render(); }
  },
  dropGear(id, i) {
    const f = gang.fighters.find((x) => x.id === id);
    if (f) { f.gear.splice(i, 1); render(); }
  },
  toggleArm(i) {
    const name = gangDef().equipment[i]?.name;
    if (!name) return;
    openArm.has(name) ? openArm.delete(name) : openArm.add(name);
    render();
  },
  save() {
    const s = saves();
    s[gang.name] = gang;
    setSaves(s);
    toast(`Saved "${gang.name}"`);
    render();
  },
  load(i) {
    const s = saves();
    const name = Object.keys(s)[i];
    if (!name) return;
    gang = s[name];
    render();
  },
  del(i) {
    const s = saves();
    const name = Object.keys(s)[i];
    if (!name || !confirm(`Delete gang "${name}"?`)) return;
    delete s[name];
    setSaves(s);
    toast('Deleted');
    render();
  },
  exportSheet() {
    const g = gangDef();
    const line = (c = '-') => c.repeat(58);
    let txt = `${gang.name.toUpperCase()}\n${g.name} — ${g.book}\n`;
    txt += `Budget ${gang.budget}cr — spent ${spent()}cr — gang rating ${spent()}\n`;
    txt += `House skill: ${g.houseSkill}\n${line('=')}\n`;
    for (const f of gang.fighters) {
      const def = fighterDef(f.type);
      if (!def) continue;
      txt += `\n${(f.label || def.name).toUpperCase()} — ${def.name} (${def.category}) — ${fighterTotal(f)}cr\n`;
      txt += statSummary(def.stats) + '\n';
      txt += f.gear.length
        ? 'Gear: ' + f.gear.map((x) => `${x} (${equipDef(x)?.cost ?? '?'}cr)`).join(', ') + '\n'
        : 'Gear: none\n';
      const wProfiles = f.gear.map((x) => [x, CAT.weapons[x]]).filter(([, w]) => w && w.profiles.length);
      for (const [name, w] of wProfiles) {
        for (const p of w.profiles) {
          txt += `  ${name}${p.name ? ' (' + p.name + ')' : ''}: Rng ${p.rngS}/${p.rngL} Acc ${p.accS}/${p.accL} S${p.str} AP${p.ap} D${p.d} Am${p.ammo}${p.traits ? ' — ' + p.traits : ''}\n`;
        }
      }
    }
    txt += `\n${line('=')}\nRaising Havok Gaming Club — built ${new Date().toISOString().slice(0, 10)}\n`;
    txt += `Catalog: ${CAT.meta.edition}. ${CAT.meta.caveats[0]}\n`;

    const back = document.createElement('div');
    back.className = 'modal-back';
    back.innerHTML = `<div class="modal">
      <button class="modal-x" onclick="this.closest('.modal-back').remove()">✕</button>
      <h2>${esc(gang.name)}</h2>
      <div class="export-pre">${esc(txt)}</div>
      <div class="modal-actions no-print">
        <button class="btn small" id="copy-btn">Copy text</button>
        <button class="btn small ghost" onclick="window.print()">Print</button>
      </div>
    </div>`;
    back.addEventListener('click', (e) => { if (e.target === back) back.remove(); });
    back.querySelector('#copy-btn').onclick = () => {
      navigator.clipboard.writeText(txt).then(() => toast('Copied'), () => toast('Copy failed'));
    };
    document.body.append(back);
  },
};
window.NM = NM;

// ---------------------------------------------------------------- boot

async function boot() {
  try {
    const cfg = await fetch('/api/config').then((r) => r.json());
    discordSso = Boolean(cfg.discordEnabled);
  } catch { /* config is best-effort */ }

  try {
    me = await api('/me');
  } catch {
    me = null;
  }
  const who = document.getElementById('whoami');
  if (who) who.textContent = me ? `👤 ${me.name}` : '';
  if (!me) { loginWall(); return; }

  try {
    CAT = await api('/builders/necromunda/catalog');
  } catch (e) {
    $app.innerHTML = `<div class="card"><p class="error">Could not load the Necromunda catalog: ${esc(e.message)}</p></div>`;
    return;
  }
  render();
}

boot();
